    91	fn get_ruf_impact(conn: Arc<Mutex<Client>>) -> HashMap<i32, Vec<String>> {
    92	    conn.lock().unwrap().
    93	        query("DROP TABLE IF EXISTS tmp_ruf_remediation_analysis;", &[]).unwrap();
    94	    conn.lock().unwrap().
    95	        query(r#"CREATE TABLE tmp_ruf_remediation_analysis AS (
    96	            SELECT DISTINCT id, feature FROM version_feature
    97	            WHERE feature != 'no_feature_used'
    98	        );"#, &[]).unwrap();
    99	    conn.lock().unwrap().
   100	        query(r#"INSERT INTO tmp_ruf_remediation_analysis
   101	        SELECT DISTINCT version_from, feature FROM version_feature 
   102	        INNER JOIN dep_version ON version_to=id WHERE conds = '' AND feature IS NOT NULL;"#, &[]).unwrap();
   103	    conn.lock().unwrap().
   104	        query(r#"INSERT INTO tmp_ruf_remediation_analysis
   105	        SELECT  DISTINCT version_from, nightly_feature FROM dep_version_feature;"#, &[]).unwrap();
   106	    let query = format!(
   107	        "SELECT DISTINCT id, feature FROM tmp_ruf_remediation_analysis;"
   108	    );
   109	    let rows = conn.lock().unwrap().query(&query, &[]).unwrap();
   110	    let mut ruf_impact: HashMap<i32, Vec<String>> = HashMap::new();
   111	    for ver in rows{
   112	        let version_id:i32 = ver.get(0);
   113	        let name:&str = ver.get(1);
   114	        let id = ruf_impact.entry(version_id).or_insert(Vec::new());
   115	        (*id).push(name.to_string());
   116	    }
