   121	/// Return the best ruf status through all rustc version where specific package version is using. This represents that the version can be safety recovered.
   122	///     Arg: ruf_impact: Vec<RUF>, rustc_version: Specify rustc_version where RUF is running, lifetime_table: RUF lifetime
   123	///     Return: Worst ruf status. Can be "stable", "unstable" (including "active" and "imcomplete"), "failure" (including "removed" and "unknown").
   124	///             Also, return the recovery point.
   125	fn get_version_ruf_status_all(ruf_impact: &Vec<String>, lifetime_table: &HashMap<&'static str, [&'static str; RUSTC_VER_NUM]> ) -> (&'static str, usize){
   126	    let mut final_status = "failure";
   127	    let mut recovery_point = MAX_RUSTC_VERSION;
   128	    for i in (0..(MAX_RUSTC_VERSION + 1)).rev(){
   129	        let status = get_version_ruf_status(ruf_impact, i, lifetime_table);
   130	        match status {
   131	            "stable" => return ("stable", i),
   132	            "unstable" => {
   133	                if final_status != "unstable" {
   134	                    recovery_point = i;
   135	                }
   136	                final_status = "unstable";
   137	            }
   138	            _ => (),
   139	        };
   140	    }
   141	    (final_status, recovery_point )
   142	}
   143	
   144	/// Return the worst ruf status (given rustc version) where specific package version is using. This represents that whether the version can be safety used.
   145	///     Arg: ruf_impact: Vec<RUF>, rustc_version: Specify rustc_version where RUF is running, lifetime_table: RUF lifetime
   146	///     Return: Worst ruf status. Can be "stable", "unstable" (including "active" and "imcomplete"), "failure" (including "removed" and "unknown").
   147	fn get_version_ruf_status(ruf_impact: &Vec<String>, rustc_version:usize, lifetime_table: &HashMap<&'static str, [&'static str; RUSTC_VER_NUM]> ) -> &'static str{
   148	    let mut status = "stable";
   149	    for ruf in ruf_impact{
   150	        if let Some(ruf_status) = get_ruf_status(lifetime_table, ruf.as_str(), rustc_version){
   151	            if ruf_status == "active" || ruf_status == "imcomplete" {
   152	                status = "unstable";
   153	            }
   154	            else if ruf_status == "removed"{
   155	                return "failure";
   156	            }
   157	        }
   158	        else{
   159	            return "failure";
   160	        }
   161	    }
   162	    status
   163	}
